insert into public.config_version(id,kind,version,effective_at,status,placeholder,definition,drafted_by,approved_by,approved_at) values('40000000-0000-4000-8000-000000000001','sop',1,'2026-01-01','approved',true,'{"session_inactivity_minutes":30,"session_offline_days":7,"reception_measurements":[{"key":"ph","min":4,"max":6,"required":true},{"key":"reception_temperature","min":0,"max":10,"required":true}],"packaging_options":["kraft","transparent","vacuum","container"],"shelf_life_by_package":{"kraft":180,"transparent":180,"vacuum":180,"container":180},"label_template":{"product":{"en":"Whey kishk","ar":"كشك بمصل الحليب"},"ingredients":{"en":["Whey","Bulgur","Salt"],"ar":["مصل الحليب","برغل","ملح"]},"allergens":{"en":["Milk","Gluten"],"ar":["الحليب","الغلوتين"]},"storage_advice":{"en":"Keep cool and dry","ar":"يحفظ بمكان بارد وجاف"}},"expected_yield":{"min":0.1,"max":2},"multi_lot":true,"blending_enabled":false,"self_release":false,"lab_before_release":false,"whey_max_age_hours":48,"shelf_life_days":180,"stages":[{"key":"preparation","label":{"en":"Preparation","ar":"التحضير"}},{"key":"mixing","label":{"en":"Mixing","ar":"الخلط"}},{"key":"fermentation","label":{"en":"Fermentation","ar":"التخمير"}},{"key":"drying","label":{"en":"Drying","ar":"التجفيف"}},{"key":"grinding","label":{"en":"Grinding & sieving","ar":"الطحن والنخل"}},{"key":"packing","label":{"en":"Ready to pack","ar":"جاهز للتعبئة"}}],"checkpoints":[{"key":"hygiene","help_module_key":"gmp","help_step":0,"stage":"preparation","response_type":"boolean","severity":"critical","checklist_items":[{"key":"equipment","label":{"en":"Equipment cleaned and sanitized","ar":"تنظيف وتعقيم المعدات"}},{"key":"area","label":{"en":"Production area clean","ar":"منطقة الإنتاج نظيفة"}},{"key":"personal","label":{"en":"Personal hygiene checked","ar":"التحقق من النظافة الشخصية"}},{"key":"ingredients","label":{"en":"Ingredients inspected","ar":"فحص المكونات"}},{"key":"containers","label":{"en":"Containers protected","ar":"حماية الحاويات"}},{"key":"protection","label":{"en":"Equipment protected from contamination","ar":"حماية المعدات من التلوث"}}],"label":{"en":"Pre-production hygiene","ar":"النظافة قبل الإنتاج"},"required":true},{"key":"drying_temperature","help_module_key":"gmp","help_step":1,"stage":"drying","label":{"en":"Drying inspection","ar":"فحص التجفيف"},"required":true,"unit":"°C","min":10,"max":50,"min_plausible":-20,"max_plausible":150,"interval_hours":12,"severity":"major"}]}','20000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000005',now());
insert into public.supplier values('50000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','Cedar Dairy','dairy','approved','{}','{"pasteurized":true,"starter_culture":"Cultured labneh","salt_stage":"After separation"}');
insert into public.training_module(id,config_version_id,module_key,version,content,assessment) values('70000000-0000-4000-8000-000000000001','40000000-0000-4000-8000-000000000001','gmp',1,'{"title":{"en":"Good practice and traceable records","ar":"الممارسات الجيدة والسجلات القابلة للتتبع"},"en":"Use the approved cooperative SOP for production. These introductory examples explain clean equipment, evidence capture and traceable records; the placeholder protocol needs Food-Safety Lead approval.","ar":"اتبع إجراءات التشغيل المعتمدة في التعاونيات. توضح هذه الأمثلة التمهيدية نظافة المعدات وتسجيل الأدلة والسجلات القابلة للتتبع؛ يحتاج البروتوكول المؤقت إلى موافقة مسؤول سلامة الغذاء.","steps":[{"title":{"en":"Check equipment before work","ar":"افحص المعدات قبل العمل"},"text":{"en":"Confirm each item in the approved hygiene checklist. Record an exception when something is not ready; ask the supervisor before proceeding.","ar":"أكد كل بند في قائمة النظافة المعتمدة. سجّل استثناءً عندما لا يكون شيء جاهزاً واسأل المشرف قبل المتابعة."},"illustration":"clean_equipment"},{"title":{"en":"Capture the display and confirm the value","ar":"صوّر الشاشة وأكد القيمة"},"text":{"en":"Photograph the instrument without faces. Enter or confirm the displayed reading and unit. An OCR suggestion is assistance; your confirmed value is the record.","ar":"صوّر الجهاز دون وجوه. أدخل أو أكد القراءة والوحدة الظاهرة. اقتراح قراءة الصورة للمساعدة؛ القيمة التي تؤكدها هي السجل."},"illustration":"clean_equipment"},{"title":{"en":"Keep the lot connection","ar":"حافظ على الربط بالدفعة"},"text":{"en":"Select the actual received lot and record the quantity used. Never substitute a rejected, held or expired input. Save and check the synchronization status.","ar":"اختر الدفعة المستلمة الفعلية وسجّل الكمية المستخدمة. لا تستبدلها بمادة مرفوضة أو معلقة أو منتهية الصلاحية. احفظ السجل وتحقق من حالة المزامنة."},"illustration":"protected_container"}],"faqs":[{"question":{"en":"Does saving a checkpoint release the batch?","ar":"هل حفظ الفحص يجيز طرح الدفعة؟"},"answer":{"en":"No. An authorized reviewer makes a separate release decision after reviewing the required records and deviations.","ar":"لا. يتخذ المراجع المصرّح له قراراً منفصلاً بعد مراجعة السجلات والانحرافات المطلوبة."}},{"question":{"en":"Can I keep working without a connection?","ar":"هل يمكنني متابعة التسجيل دون اتصال؟"},"answer":{"en":"Save permitted records on the device and synchronize later. Check the status after each save. Release, recall and critical deviation closure require a connection.","ar":"احفظ السجلات المسموحة على الجهاز وزامنها لاحقاً. تحقق من الحالة بعد كل حفظ. يتطلب الطرح والاستدعاء وإغلاق الانحراف الحرج اتصالاً."}}],"troubleshooting":[{"issue":{"en":"The reading is uncertain","ar":"القراءة غير واضحة"},"action":{"en":"Keep the photo, enter the value manually if you can confirm it, or record a deviation and ask the supervisor.","ar":"احتفظ بالصورة وأدخل القيمة يدوياً إذا أمكن تأكيدها أو سجّل انحرافاً واسأل المشرف."}},{"issue":{"en":"A record shows a sync conflict","ar":"السجل يظهر تعارض مزامنة"},"action":{"en":"Do not repeat or silently replace the record. The supervisor reviews the saved original and creates an attributed correction.","ar":"لا تكرر السجل أو تستبدله بصمت. يراجع المشرف الأصل المحفوظ ويسجّل تصحيحاً منسوباً لصاحبه."}}],"resources":[]}','[{"key":"hygiene","question":{"en":"Which equipment is ready to check before use?","ar":"أي معدات جاهزة للفحص قبل الاستخدام؟"},"correct":"safe","options":[{"key":"safe","illustration":"clean_equipment","label":{"en":"Clean equipment","ar":"معدات نظيفة"}},{"key":"unsafe","illustration":"dirty_equipment","label":{"en":"Equipment with residues","ar":"معدات عليها بقايا"}}]}]');
