insert into public.kpi_definition values('KPI-01','Whey received (kg)','Mass of whey recorded at receipt','Whey lots','Sum received mass','Test data','Coop, project, donor');
insert into public.kpi_definition values('KPI-02','Whey accepted (kg)','Mass with decision Accepted','Whey lots','Sum where decision = Accepted','Lots later reclassified by amendment use latest decision','Coop, project, donor');
insert into public.kpi_definition values('KPI-03','Whey valorized (kg)','Accepted whey consumed by batches that reached Released','Allocations','Sum allocations to released batches','Abandoned or rejected batches','Project, donor');
insert into public.kpi_definition values('KPI-04','Whey utilization rate (%)','KPI-03 ÷ KPI-02','Derived','Ratio × 100','—','Project, donor');
insert into public.kpi_definition values('KPI-05','Kishk packaged (kg)','Net mass in packaging lots','Packaging lots','Sum packaged mass','Rejected batches','Coop, project, donor');
insert into public.kpi_definition values('KPI-06','Kishk output per kg whey','KPI-05 ÷ whey input to the same batches','Derived','Ratio','Batches without complete allocation','Project');
insert into public.kpi_definition values('KPI-07','Active producer','Producer recording at least one qualifying activity in the period','Production records','Distinct qualified users','Test and deactivated accounts','Project, donor (aggregate)');
insert into public.kpi_definition values('KPI-08','Trained producer','Producer with all required current modules completed','Training completions','Distinct users','Expired refreshers','Project, donor');
insert into public.kpi_definition values('KPI-09','Record completeness (%)','Required records completed ÷ required records due','Checkpoints','Ratio across batches in period','Draft batches','Coop, project');
insert into public.kpi_definition values('KPI-10','Recorded gross sales (USD)','Value of sale transactions','Sales','Sum of totals converted at stored rate','Donations, returns','Coop, project, donor');
insert into public.kpi_definition values('KPI-11','Units sold','Packages in sale transactions','Sales','Sum quantity','Returns','Coop, project, donor');
insert into public.kpi_definition values('KPI-12','Open critical deviations','Critical deviations not closed','Deviations','Count at period end','—','Coop, project');
insert into public.kpi_definition values('KPI-13','Mock-recall time (min)','Time to complete a mock recall trace','Recall cases','Duration','—','Project');
